SELECT pg_temp.assert_erp(NOT has_table_privilege('comecore_runtime','cms.revisions','UPDATE,DELETE') AND NOT has_table_privilege('comecore_runtime','cms.publications','UPDATE,DELETE'),'versiones/publicaciones inmutables para runtime');
