SELECT set_config('app.user_id','73100000-0000-4000-8000-000000000002',true);
SELECT pg_temp.assert_erp((SELECT count(*)>0 FROM inventory.assets) AND (SELECT count(*)=0 FROM billing.invoices) AND (SELECT count(*)=0 FROM documents.files),'support consulta inventario, no facturación/archivos');
WITH mutated AS (UPDATE inventory.assets SET notes='forbidden' RETURNING id) SELECT pg_temp.assert_erp((SELECT count(*)=0 FROM mutated),'support no modifica inventario');
